/**
 * @backupGlobals disabled
 * @backupStaticAttributes enabled
 */
class ScrumboardTest extends CommonClassTest
{
	const FAKE_PROJECT_ID = 987654;

	/**
	 * @return void
	 */
	protected function setUp(): void
	{
		global $conf, $user, $langs, $db;

		parent::setUp();
		$conf = $this->savconf;
		$user = $this->savuser;
		$langs = $this->savlangs;
		$db = $this->savdb;
		$GLOBALS['hookmanager'] = new HookManager($db);
		$GLOBALS['hookmanager']->initHooks(array('scrumboardinterface'));
		$db->begin();
	}

	/**
	 * @return void
	 */
	protected function tearDown(): void
	{
		global $db;

		$db->rollback();
		parent::tearDown();
	}

	/**
	 * @param  int    $order Order of the story
	 * @param  string $label Label of the story
	 * @return TStory
	 */
	private function createStory($order, $label)
	{
		global $db;

		$story = new TStory($db);
		$story->fk_projet = self::FAKE_PROJECT_ID;
		$story->storie_order = $order;
		$story->label = $label;
		$this->assertGreaterThan(0, $story->save(), $story->error);

		return $story;
	}

	/**
	 * @return void
	 */
	public function testStoryIsCreatedLoadedAndDeleted()
	{
		global $db;

		$story = $this->createStory(1, 'Sprint \'quoted\'');
		$this->assertGreaterThan(0, $story->id);

		$loaded = new TStory($db);
		$this->assertSame($story->id, $loaded->loadStory(self::FAKE_PROJECT_ID, 1));
		$this->assertSame('Sprint \'quoted\'', $loaded->label);
		$this->assertSame(1, $loaded->visible);

		$this->assertGreaterThan(0, $loaded->delete());
		$this->assertSame(0, (new TStory($db))->loadStory(self::FAKE_PROJECT_ID, 1));
	}

	/**
	 * @return void
	 */
	public function testStoriesOfAProjectComeOrderedAndToggleHidesOne()
	{
		global $db;

		$second = $this->createStory(2, 'Second');
		$this->createStory(1, 'First');

		$stories = (new TStory($db))->getAllStoriesFromProject(self::FAKE_PROJECT_ID);
		$this->assertSame(array('First', 'Second'), array_map(function ($story) {
			return $story->label;
		}, $stories));

		$this->assertGreaterThan(0, $second->toggleVisibility());
		$reloaded = new TStory($db);
		$reloaded->load($second->id);
		$this->assertSame(0, $reloaded->visible);
	}

	/**
	 * @return void
	 */
	public function testColumnsAreLoadedByRankAndFilteredByEntity()
	{
		global $db, $conf;

		$column = new ScrumboardColumn();
		$columns = $column->LoadAllBy($db, array('entity' => $conf->entity, 'active' => 1));

		$this->assertNotEmpty($columns, 'the module seeds its columns');
		$ranks = array_map(function ($col) {
			return (int) $col->rang;
		}, $columns);
		$sorted = $ranks;
		sort($sorted);
		$this->assertSame($sorted, $ranks);
		$this->assertSame(array(), $column->LoadAllBy($db, array('code' => 'no-such-column')));
	}

	/**
	 * The filters of the board are cast before they reach the query.
	 *
	 * @return void
	 */
	public function testTaskQueryCastsItsFilters()
	{
		global $db;

		$task = new Task($db);
		$extrafields = new ExtraFields($db);
		$sql = getSQLForTasks($db, '1 OR 1=1', 'todo', '5; DROP TABLE x', '7 OR 1=1', 'both', array(0, 0, 0, 0), array(), $task, $extrafields, "x' OR '1'='1", '3 OR 1=1', '4 UNION SELECT 1');

		$this->assertIsString($sql);
		$this->assertStringNotContainsString('DROP TABLE', $sql);
		$this->assertStringNotContainsString('1=1', $sql);
		$this->assertStringNotContainsString('UNION', $sql);
		$this->assertStringContainsString("x\\' OR \\'1\\'=\\'1", $sql);
	}

	/**
	 * Only the label, progress, status, column and sprint of a task can be set from a request.
	 *
	 * @return void
	 */
	public function testTaskUpdateIgnoresOtherFields()
	{
		global $db;

		$resql = $db->query('SELECT rowid, fk_projet FROM '.$db->prefix().'projet_task ORDER BY rowid LIMIT 1');
		$row = $resql ? $db->fetch_object($resql) : null;
		if (!$row) {
			$this->markTestSkipped('No task in the test database');
		}

		$details = getTaskDetailsForScrumboardCard($db, (int) $row->rowid, array(
			'label' => 'Scrumboard test label',
			'progress' => 250,
			'status' => 'inprogress',
			'story_k' => 1,
			'scrum_status' => 'todo',
			'fk_project' => 987654,
			'fk_task_parent' => 987654,
			'planned_workload' => 999999,
		));

		$check = new Task($db);
		$check->fetch((int) $row->rowid);
		$this->assertSame('Scrumboard test label', $check->label);
		$this->assertEquals($row->fk_projet, $check->fk_project, 'the project of a task cannot be changed from the board');
		$this->assertNotEquals(999999, (int) $check->planned_workload);
		$this->assertLessThanOrEqual(100, (int) $check->progress);
	}
}
